/**
 * Derives an owner's numeric membership level. Starts at {@code 1}, plus {@code 1} when an email
 * is present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
 * {@code 1} when the owner belongs to a household of at least three members. Level {@code 4}
 * additionally requires a tenure of more than {@code 365} days (the number of days between the
 * owner's registration date and the current server date); without that tenure the level is
 * capped at {@code 3}. Because a newly created owner registers on the current date, its tenure is
 * zero, so a new owner never exceeds level {@code 3} even with every other factor present.
 *
 * @param owner the owner to derive the membership level for
 * @return the membership level, between {@code 1} and {@code 4}
 */
default Integer membershipLevel(Owner owner) {
    int level = 1;
    String email = owner.getEmail();
    if (email != null && !email.isBlank()) {
        level++;
    }
    Integer namesakeCount = owner.getNamesakeCount();
    if (namesakeCount != null && namesakeCount == 0) {
        level++;
    }
    Integer householdMemberCount = owner.getHouseholdMemberCount();
    if (householdMemberCount != null && householdMemberCount >= 3) {
        level++;
